{"content": "import fs from 'node:fs';
import readline from 'node:readline';

const file = process.argv[2];
const mode = process.argv[3] || 'users';
const rl = readline.createInterface({ input: fs.createReadStream(file, 'utf8'), crlfDelay: Infinity });
let i = 0;
const out = [];

function textOf(d) {
  if (typeof d === 'string') return d;
  if (!d || typeof d !== 'object') return '';
  if (typeof d.text === 'string') return d.text;
  if (typeof d.message === 'string') return d.message;
  if (Array.isArray(d.content)) {
    return d.content.map(c => (typeof c === 'string' ? c : (c?.text ?? ''))).join('\n');
  }
  if (typeof d.content === 'string') return d.content;
  return JSON.stringify(d).slice(0, 4000);
}

for await (const line of rl) {
  if (!line.trim()) continue;
  i++;
  let o;
  try { o = JSON.parse(line); } catch { continue; }
  if (mode === 'users' && o.type === 'user/message') {
    out.push(`\n===== [line ${i}] USER =====\n${textOf(o.data).slice(0, 6000)}`);
  } else if (mode === 'assist' && o.type === 'assistant/message') {
    out.push(`\n===== [line ${i}] ASSISTANT =====\n${textOf(o.data).slice(0, 4000)}`);
  } else if (mode === 'tools' && o.type === 'tool/call') {
    const d = o.data ?? {};
    out.push(`[${i}] ${d.name ?? d.toolName ?? '?'} :: ${JSON.stringify(d.arguments ?? d.args ?? d.input ?? {}).slice(0, 400)}`);
  }
}
console.log(out.join('\n'));
", "file_path": "C:\Users\limer\Desktop\motor-drive\Soft\_mem\extract2.mjs"}

