{"content": "import { DatabaseSync } from "node:sqlite";
import zlib from "node:zlib";

const db = new DatabaseSync(process.argv[2], { readOnly: true });

function tryDecode(s) {
  if (typeof s !== "string" || !s) return null;
  let raw;
  try { raw = Buffer.from(s, "base64"); } catch { return null; }
  const attempts = [
    ["zlib", () => zlib.inflateSync(raw)],
    ["gzip", () => zlib.gunzipSync(raw)],
    ["deflate-raw", () => zlib.inflateRawSync(raw)],
    ["brotli", () => zlib.brotliDecompressSync(raw)],
    ["utf8-plain", () => raw],
  ];
  for (const [name, fn] of attempts) {
    try { return { how: name, buf: fn() }; } catch {}
  }
  return null;
}

const tbl = "project_history_f3076911cd244e90aa774d2e469fb6e7";
console.log("cols:", db.prepare(`PRAGMA table_info("${tbl}")`).all().map(c => `${c.name}:${c.type}`).join(", "));
const rows = db.prepare(`SELECT * FROM "${tbl}" ORDER BY id DESC LIMIT 6`).all();
for (const r of rows) {
  const brief = {};
  for (const [k, v] of Object.entries(r)) {
    brief[k] = (typeof v === "string" && v.length > 120) ? `${v.slice(0, 120)}…(len=${v.length})` : v;
  }
  console.log("\n---", JSON.stringify(brief));
}
// decode the newest row that has a decodable payload
for (const r of rows) {
  for (const key of Object.keys(r)) {
    const v = r[key];
    if (typeof v !== "string" || v.length < 100) continue;
    const d = tryDecode(v);
    if (!d) continue;
    const text = d.buf.toString("utf8");
    console.log(`\n### decoded col=${key} how=${d.how} bytes=${d.buf.length}`);
    console.log(text.slice(0, 1500));
    break;
  }
}
