{"content": "import { DatabaseSync } from "node:sqlite";
import zlib from "node:zlib";

const db = new DatabaseSync(process.argv[2], { readOnly: true });

function tryDecode(s) {
  if (typeof s !== "string" || !s) return null;
  let raw;
  try { raw = Buffer.from(s, "base64"); } catch { return null; }
  for (const [name, fn] of [
    ["zlib", () => zlib.inflateSync(raw)],
    ["gzip", () => zlib.gunzipSync(raw)],
    ["raw", () => zlib.inflateRawSync(raw)],
    ["brotli", () => zlib.brotliDecompressSync(raw)],
    ["plain", () => raw],
  ]) {
    let out;
    try { out = fn(); } catch { continue; }
    const t = out.toString("utf8");
    // heuristic: printable
    const printable = t.slice(0, 400).replace(/[^\x09\x0a\x0d\x20-\x7e\u4e00-\u9fff]/g, "").length / Math.min(400, t.length || 1);
    return { how: name, buf: out, text: t, printable };
  }
  return null;
}

const all = db.prepare("SELECT id,uuid,history_uuid,dataStr,created_at,updated_at FROM history_data ORDER BY id").all();
console.log("history_data rows:", all.length);

const results = [];
for (const r of all) {
  const d = tryDecode(r.dataStr);
  if (!d) { results.push({ id: r.id, how: "FAIL", len: r.dataStr.length }); continue; }
  const t = d.text;
  const marks = [];
  for (const k of ["Schematic", "components", "wires", "netFlag", "sheet", "libDevice", "uuid", "vertices", "pcb", "Device"]) {
    if (t.includes(`"${k}"`)) marks.push(k);
  }
  results.push({ id: r.id, how: d.how, bytes: d.buf.length, json: t.trimStart()[0] === "{", marks: marks.join(","), head: t.slice(0, 90).replace(/\s+/g, " ") });
}
for (const r of results) console.log(JSON.stringify(r));
