{"content": "/**
 * 网表自检：把 NETS 反向展开成 引脚→网络，逐条校验。
 * 只要有任何一个引脚"未连接"或"被两个网络同时占用"，就报错退出。
 */
import { COMPONENTS, NETS, SYMBOL_PINS } from './design.mjs';

const errors = [];
const warns = [];

/* --- 1. 位号唯一 --- */
const byRef = new Map();
for (const c of COMPONENTS) {
  if (byRef.has(c.ref)) errors.push(`位号重复: ${c.ref}`);
  if (!SYMBOL_PINS[c.sym]) errors.push(`未知符号类型: ${c.ref} -> ${c.sym}`);
  byRef.set(c.ref, c);
}

/* --- 2. 每个引脚 → 所在网络 --- */
const pinNet = new Map(); // "R1.1" -> netName
for (const [net, members] of Object.entries(NETS)) {
  for (const m of members) {
    const dot = m.lastIndexOf('.');
    const ref = m.slice(0, dot), pin = m.slice(dot + 1);
    const comp = byRef.get(ref);
    if (!comp) { errors.push(`网络 ${net} 引用了不存在的元件: ${m}`); continue; }
    const valid = SYMBOL_PINS[comp.sym];
    if (!valid.includes(pin)) { errors.push(`网络 ${net} 引用了非法引脚: ${m} (${comp.sym} 合法引脚: ${valid.join('/')})`); continue; }
    if (pinNet.has(m)) { errors.push(`引脚被两个网络占用: ${m} → ${pinNet.get(m)} 和 ${net}`); continue; }
    pinNet.set(m, net);
  }
}

/* --- 3. 引脚全覆盖 --- */
let totalPins = 0;
for (const c of COMPONENTS) {
  for (const p of SYMBOL_PINS[c.sym]) {
    totalPins++;
    if (!pinNet.has(`${c.ref}.${p}`)) errors.push(`引脚未连接: ${c.ref}.${p} (${c.sym} ${c.val})`);
  }
}

/* --- 4. 单脚网络 / 空网络 --- */
for (const [net, members] of Object.entries(NETS)) {
  if (members.length === 0) errors.push(`空网络: ${net}`);
  else if (members.length === 1) warns.push(`单脚网络（悬空）: ${net} = ${members[0]}`);
}

/* --- 5. 每个元件至少在一个网络里 --- */
for (const c of COMPONENTS) {
  const used = SYMBOL_PINS[c.sym].some(p => pinNet.has(`${c.ref}.${p}`));
  if (!used) errors.push(`元件完全未使用: ${c.ref}`);
}

/* ---------------- 报告 ---------------- */
console.log('='.repeat(72));
console.log('网表自检报告');
console.log('='.repeat(72));
console.log(`元件数         : ${COMPONENTS.length}`);
console.log(`引脚总数       : ${totalPins}`);
console.log(`已连接引脚     : ${pinNet.size}`);
console.log(`网络数         : ${Object.keys(NETS).length}`);
console.log('');

/* 按类别统计 */
const { NET_CLASS } = await import('./design.mjs');
const byClass = {};
for (const n of Object.keys(NETS)) {
  const c = NET_CLASS[n] ?? 'other';
  byClass[c] = (byClass[c] ?? 0) + 1;
}
console.log('网络分类       :', Object.entries(byClass).map(([k, v]) => `${k}=${v}`).join('  '));
console.log('');

/* 关键网络人工核对 */
console.log('--- 关键网络 ---');
for (const n of ['SW', 'LS_STAR', 'VCC', 'VB1', 'VB2', 'VB3', 'PH_A', 'PH_B', 'PH_C',
                 'VN', 'VS_A', 'GL_A', 'GH_A', 'EN', 'PSND', 'PGND', 'AGND']) {
  if (!NETS[n]) continue;
  console.log(`  ${n.padEnd(10)} (${String(NETS[n].length).padStart(2)}) : ${NETS[n].join(' ')}`);
}

if (warns.length) {
  console.log('\n--- 警告 ---');
  for (const w of warns) console.log('  ⚠ ' + w);
}
if (errors.length) {
  console.log('\n--- 错误 ---');
  for (const e of errors) console.log('  ✗ ' + e);
  console.log(`\n自检失败：${errors.length} 个错误`);
  process.exit(1);
}
console.log('\n✓ 自检通过：所有引脚均已连接，无重复占用，无悬空网络。');
", "file_path": "C:\Users\limer\Desktop\motor-drive\Soft\_gen\verify.mjs"}

