{"content": "/**
 * KiCad 8 原理图生成器
 * 策略：所有符号旋转 0°，每个引脚向外拉一小段线并挂一个「全局标签」。
 *       KiCad 按标签名合并网络 —— 连接关系由标签保证，不依赖长走线，
 *       因此不会出现"线没连上"的隐性错误。
 * 坐标变换：符号空间 +Y 向上，图纸空间 +Y 向下 → sheet = (X + px, Y − py)
 */
import { COMPONENTS, NETS, SYMBOL_PINS, PIN_NAMES, PROJECT } from './design.mjs';

/* ---------------- 确定性 UUID ---------------- */
let uuidSeq = 0;
const uuid = () => {
  uuidSeq++;
  const h = uuidSeq.toString(16).padStart(12, '0');
  return `a0000000-0000-4000-8000-${h}`;
};
const ROOT_UUID = 'a0000000-0000-4000-8000-000000000001';

/* ============================================================
   符号库：引脚几何 + 图形
   2 脚元件统一竖向：pin1 在上 (0,3.81)，pin2 在下 (0,−3.81)
   ============================================================ */
const G = (w = 0.254) => `(stroke (width ${w}) (type default)) (fill (type none))`;
const GF = (w = 0.254) => `(stroke (width ${w}) (type default)) (fill (type background))`;
const rect = (x1, y1, x2, y2, filled = false) =>
  `(rectangle (start ${x1} ${y1}) (end ${x2} ${y2}) ${filled ? GF() : G()})`;
const poly = (pts, w = 0.254) =>
  `(polyline (pts ${pts.map(([x, y]) => `(xy ${x} ${y})`).join(' ')}) ${G(w)})`;

/* 两脚元件通用引脚 */
const P2 = [
  { n: '1', x: 0, y: 3.81, a: 270, l: 1.27, t: 'passive' },
  { n: '2', x: 0, y: -3.81, a: 90, l: 1.27, t: 'passive' },
];

const SYMDEFS = {
  R: { pins: P2, gfx: [rect(-1.016, -2.54, 1.016, 2.54)], refAt: [2.54, 1.27], valAt: [2.54, -1.27] },
  RSHUNT: { pins: P2, gfx: [rect(-1.27, -2.54, 1.27, 2.54)], refAt: [3.048, 1.27], valAt: [3.048, -1.27] },
  FUSE: { pins: P2, gfx: [rect(-1.016, -2.54, 1.016, 2.54), poly([[0, -2.54], [0, 2.54]], 0.508)], refAt: [2.54, 1.27], valAt: [2.54, -1.27] },
  C: {
    pins: P2,
    gfx: [poly([[-1.524, 0.508], [1.524, 0.508]], 0.4064), poly([[-1.524, -0.508], [1.524, -0.508]], 0.4064)],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  CP: {
    pins: P2,
    gfx: [
      poly([[-1.524, 0.508], [1.524, 0.508]], 0.4064),
      poly([[-1.524, -0.508], [1.524, -0.508]], 0.4064),
      poly([[-1.778, 1.524], [-1.016, 1.524]]), poly([[-1.397, 1.143], [-1.397, 1.905]]),
    ],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  L: {
    pins: P2,
    gfx: [poly([[0, 2.54], [0, -2.54]], 0.254), poly([[-1.27, 2.54], [1.27, 2.54]]), poly([[-1.27, -2.54], [1.27, -2.54]])],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  D: {
    pins: P2,
    gfx: [poly([[-1.27, 1.27], [1.27, 1.27], [0, -1.27], [-1.27, 1.27]], 0.254), poly([[-1.27, -1.27], [1.27, -1.27]], 0.254)],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  DSCH: {
    pins: P2,
    gfx: [
      poly([[-1.27, 1.27], [1.27, 1.27], [0, -1.27], [-1.27, 1.27]], 0.254),
      poly([[-1.27, -1.27], [1.27, -1.27], [1.27, -1.27]], 0.254),
      poly([[-1.27, -1.27], [-1.27, -1.778]], 0.254), poly([[-1.27, -1.778], [-0.762, -1.778]], 0.254),
      poly([[1.27, -1.27], [1.27, -1.778]], 0.254), poly([[1.27, -1.778], [0.762, -1.778]], 0.254),
    ],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  DTVS: {
    pins: P2,
    gfx: [
      poly([[-1.27, 1.27], [1.27, 1.27], [0, -1.27], [-1.27, 1.27]], 0.254),
      poly([[-1.524, -0.762], [-1.27, -1.27], [-0.762, -0.254], [-0.254, -1.27], [0.254, -0.254], [0.762, -1.27], [1.27, -0.254], [1.524, -1.27]], 0.254),
    ],
    refAt: [2.54, 1.27], valAt: [2.54, -1.27],
  },
  NMOS: {
    pins: [
      { n: '4', x: -6.35, y: 0, a: 0, l: 2.54, t: 'input' },
      { n: '1', x: 5.08, y: -5.08, a: 90, l: 2.54, t: 'passive' },
      { n: '2', x: 5.08, y: -5.08, a: 90, l: 2.54, t: 'passive' },
      { n: '3', x: 5.08, y: -5.08, a: 90, l: 2.54, t: 'passive' },
