    pins: [
      ...['1', '2', '3', '4'].map((n, i) => ({ n, x: -10.16, y: 3.81 - i * 2.54, a: 0, l: 2.54, t: 'passive' })),
      ...['5', '6', '7', '8', '9'].map((n, i) => ({ n, x: 10.16, y: 5.08 - i * 2.54, a: 180, l: 2.54, t: 'passive' })),
