put('D1', 240, 32); put('C5', 258, 32);
put('D2', 240, 52); put('C6', 258, 52);
put('D3', 240, 72); put('C7', 258, 72);
put('C1', 240, 100); put('C13', 258, 100);

/* 块 D：辅助电源（右上） */
put('U2', 330, 50);
put('L1', 300, 80); put('D5', 330, 80);
put('C11', 355, 80); put('C12', 375, 80);
put('R10', 300, 105); put('R11', 320, 105);
put('R15', 300, 130); put('R16', 320, 130); put('C29', 340, 130);
