function pinPos(ref, pin) {
  const c = COMPONENTS.find(x => x.ref === ref);
  const sd = SYMDEFS[c.sym];
  const pd = sd.pins.find(p => p.n === pin);
  if (!pd) throw new Error(`符号 ${c.sym} 没有引脚 ${pin}`);
  const p = PLACE[ref];
  return { x: p.x + pd.x, y: p.y - pd.y, a: pd.a };
