  w(`  (symbol (lib_id "mdrive:${c.sym}") (at ${p.x} ${p.y} 0) (unit 1)`);
  w(`    (exclude_from_sim no) (in_bom yes) (on_board yes) (dnp no)`);
  w(`    (uuid "${uuid()}")`);
  const sd = SYMDEFS[c.sym];
  w(`    (property "Reference" "${c.ref}" (at ${p.x + sd.refAt[0]} ${p.y - sd.refAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`    (property "Value" "${esc(c.val)}" (at ${p.x + sd.valAt[0]} ${p.y - sd.valAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`    (property "Footprint" "${esc(c.fp)}" (at ${p.x} ${p.y} 0) (effects (font (size 1.27 1.27)) hide))`);
  w(`    (property "Datasheet" "" (at ${p.x} ${p.y} 0) (effects (font (size 1.27 1.27)) hide))`);
  const seen = new Set();
  for (const pd of sd.pins) {
    if (seen.has(pd.n)) continue;
    seen.add(pd.n);
    w(`    (pin "${pd.n}" (uuid "${uuid()}"))`);
  }
  w(`    (instances (project "${PROJ}" (path "/${ROOT_UUID}" (reference "${c.ref}") (unit 1))))`);
  w(`  )`);
}

/* ---- 每个引脚：短线 + 全局标签 ---- */
const pinNet = new Map();
for (const [net, members] of Object.entries(NETS))
  for (const m of members) pinNet.set(m, net);

const STUB = 5.08;
let wireCount = 0, labelCount = 0;
const collisions = [];

for (const c of COMPONENTS) {
  const sd = SYMDEFS[c.sym];
  /* 同一位置的多个引脚（如 MOSFET 的 D/S）合并成一根线 + 一个标签 */
  const groups = new Map();
  for (const pd of sd.pins) {
    const key = `${pd.x},${pd.y},${pd.a}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(pd);
  }
  for (const [, grp] of groups) {
    const nets = new Set(grp.map(pd => pinNet.get(`${c.ref}.${pd.n}`)));
    if (nets.size !== 1) throw new Error(`${c.ref} 同位置引脚却属不同网络: ${[...nets].join(',')} (引脚 ${grp.map(g => g.n).join(',')})`);
    const net = [...nets][0];
    const pp = pinPos(c.ref, grp[0].n);
    /* 引脚方向：a=0 引脚朝右（连接点在左），a=180 朝左，a=90 朝上，a=270 朝下 */
    let dx = 0, dy = 0, labelAngle = 0;
    if (pp.a === 0) { dx = -STUB; labelAngle = 180; }
    else if (pp.a === 180) { dx = STUB; labelAngle = 0; }
    else if (pp.a === 90) { dy = STUB; labelAngle = 90; }
    else if (pp.a === 270) { dy = -STUB; labelAngle = 270; }

    const x1 = round(pp.x), y1 = round(pp.y);
    const x2 = round(pp.x + dx), y2 = round(pp.y + dy);
    w(`  (wire (pts (xy ${x1} ${y1}) (xy ${x2} ${y2})) (stroke (width 0) (type default)) (uuid "${uuid()}"))`);
    wireCount++;
    w(`  (global_label "${esc(net)}" (shape passive) (at ${x2} ${y2} ${labelAngle}) (fields_autoplaced yes)`);
    w(`    (effects (font (size 1.27 1.27)) (justify ${labelAngle === 180 ? 'right' : 'left'})) (uuid "${uuid()}"))`);
    labelCount++;
  }
}

/* ---- 收尾 ---- */
w(`  (sheet_instances (path "/" (page "1")))`);
w(`)`);

function round(v) { return Math.round(v * 1000) / 1000; }

/* ---- 一致性断言：标签名必须等于设计网络名 ---- */
const designNets = new Set(Object.keys(NETS));
for (const c of COMPONENTS)
  for (const pd of SYMDEFS[c.sym].pins) {
    const net = pinNet.get(`${c.ref}.${pd.n}`);
    if (!designNets.has(net)) collisions.push(`${c.ref}.${pd.n} -> ${net}`);
  }
if (collisions.length) { console.error('网络名不一致:', collisions); process.exit(1); }

export const kicadText = out.join('\n') + '\n';
export const stats = { components: COMPONENTS.length, wires: wireCount, labels: labelCount, nets: designNets.size };
