put('F1', 30, 165); put('D4', 55, 165);
put('C2', 80, 165); put('C14', 100, 165); put('C15', 120, 165);
put('C16', 140, 165); put('C17', 160, 165);
put('C18', 185, 165); put('C19', 205, 165); put('C20', 225, 165);

/* 块 F：PWM 输入（左下） */
put('R35', 30, 215); put('R36', 60, 215); put('R37', 90, 215);
put('R38', 120, 215); put('R39', 150, 215); put('R40', 180, 215);
put('R41', 30, 240); put('R42', 60, 240); put('R43', 90, 240);
put('R44', 120, 240); put('R45', 150, 240); put('R46', 180, 240);

/* 块 G：相电压采集 + 虚拟中性点（中下，本次核心） */
put('R17', 30, 290); put('R18', 30, 310); put('C21', 48, 310); put('R23', 66, 310);
put('R19', 90, 290); put('R20', 90, 310); put('C22', 108, 310); put('R24', 126, 310);
put('R21', 150, 290); put('R22', 150, 310); put('C23', 168, 310); put('R25', 186, 310);
put('C24', 210, 310);
put('R26', 240, 310); put('C25', 258, 310);
put('R27', 280, 310); put('C26', 298, 310);
put('R28', 320, 310); put('C27', 338, 310);
put('R29', 360, 310); put('C28', 378, 310);

/* 块 H：母线采样 + 过流采样（右下） */
put('R30', 240, 215); put('R31', 240, 240); put('C30', 262, 240);
put('R32', 300, 215); put('R33', 322, 215); put('R34', 322, 240); put('C31', 348, 240);
put('R47', 380, 240);

/* 块 I：连接器（最右） */
put('J1', 330, 290);
put('J2', 380, 290);
put('J3', 60, 380);
put('J4', 300, 380);

/* ============================================================
   发射
   ============================================================ */
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
const out = [];
const w = (s = '') => out.push(s);

/* ---- 引脚绝对坐标（rotation 0） ---- */
function pinPos(ref, pin) {
  const c = COMPONENTS.find(x => x.ref === ref);
  const sd = SYMDEFS[c.sym];
  const pd = sd.pins.find(p => p.n === pin);
  if (!pd) throw new Error(`符号 ${c.sym} 没有引脚 ${pin}`);
  const p = PLACE[ref];
  return { x: p.x + pd.x, y: p.y - pd.y, a: pd.a };
}

/* ---- lib_symbols ---- */
function emitLibSymbol(name) {
  const sd = SYMDEFS[name];
  const refPrefix = name.startsWith('CONN') || name.startsWith('RSHUNT') ? '' : name;
  w(`    (symbol "mdrive:${name}"`);
  w(`      (pin_names (offset 0.762))`);
  w(`      (exclude_from_sim no) (in_bom yes) (on_board yes)`);
  w(`      (property "Reference" "${refPrefix === 'NMOS' || name === 'FD6288T' || name === 'XL7005A' ? 'U' : refPrefix === 'CONN2' || name === 'CONN3' || name === 'CONN2X8' ? 'J' : refPrefix === 'FUSE' ? 'F' : refPrefix === 'L' ? 'L' : refPrefix.startsWith('D') ? 'D' : 'R'}" (at ${sd.refAt[0]} ${sd.refAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`      (property "Value" "${name}" (at ${sd.valAt[0]} ${sd.valAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`      (property "Footprint" "" (at 0 0 0) (effects (font (size 1.27 1.27)) hide))`);
  w(`      (property "Datasheet" "" (at 0 0 0) (effects (font (size 1.27 1.27)) hide))`);
  w(`      (symbol "${name}_0_1"`);
  for (const g of sd.gfx) w(`        ${g}`);
  w(`      )`);
  w(`      (symbol "${name}_1_1"`);
  for (const p of sd.pins) {
    const nm = PIN_NAMES[name]?.[p.n] ?? (name === 'FD6288T' ? p.n : '~');
    w(`        (pin ${p.t} line (at ${p.x} ${p.y} ${p.a}) (length ${p.l})`);
    w(`          (name "${esc(nm)}" (effects (font (size 1.016 1.016))))`);
    w(`          (number "${p.n}" (effects (font (size 1.016 1.016)))))`);
  }
  w(`      )`);
  w(`    )`);
}

/* ---- 文件头 ---- */
w(`(kicad_sch`);
w(`  (version 20231120)`);
w(`  (generator "mdrive-gen")`);
w(`  (generator_version "8.0")`);
w(`  (uuid "${ROOT_UUID}")`);
w(`  (paper "A3")`);
w(`  (title_block`);
w(`    (title "${esc(PROJECT.title)}")`);
w(`    (date "${PROJECT.date}")`);
w(`    (rev "${PROJECT.rev}")`);
w(`    (comment 1 "母线 24-36V / 无感六步换向 / 过零检测由控制板 HC32F072 的 3xVC 比较器完成")`);
w(`    (comment 2 "PGND 与 AGND 经 R47(0R) 单点星接")`);
w(`  )`);
w(`  (lib_symbols`);
for (const name of Object.keys(SYMDEFS)) emitLibSymbol(name);
w(`  )`);

/* ---- 元件实例 ---- */
const PROJ = 'motor-driver';
for (const c of COMPONENTS) {
  const p = PLACE[c.ref];
  if (!p) throw new Error(`元件 ${c.ref} 未安排版面坐标`);
  w(`  (symbol (lib_id "mdrive:${c.sym}") (at ${p.x} ${p.y} 0) (unit 1)`);
  w(`    (exclude_from_sim no) (in_bom yes) (on_board yes) (dnp no)`);
  w(`    (uuid "${uuid()}")`);
  const sd = SYMDEFS[c.sym];
  w(`    (property "Reference" "${c.ref}" (at ${p.x + sd.refAt[0]} ${p.y - sd.refAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`    (property "Value" "${esc(c.val)}" (at ${p.x + sd.valAt[0]} ${p.y - sd.valAt[1]} 0) (effects (font (size 1.27 1.27)) (justify left)))`);
  w(`    (property "Footprint" "${esc(c.fp)}" (at ${p.x} ${p.y} 0) (effects (font (size 1.27 1.27)) hide))`);
  w(`    (property "Datasheet" "" (at ${p.x} ${p.y} 0) (effects (font (size 1.27 1.27)) hide))`);
  const seen = new Set();
  for (const pd of sd.pins) {
    if (seen.has(pd.n)) continue;
    seen.add(pd.n);
    w(`    (pin "${pd.n}" (uuid "${uuid()}"))`);
  }
  w(`    (instances (project "${PROJ}" (path "/${ROOT_UUID}" (reference "${c.ref}") (unit 1))))`);
  w(`  )`);
}

/* ---- 每个引脚：短线 + 全局标签 ---- */
const pinNet = new Map();
for (const [net, members] of Object.entries(NETS))
  for (const m of members) pinNet.set(m, net);

const STUB = 5.08;
let wireCount = 0, labelCount = 0;
const collisions = [];

for (const c of COMPONENTS) {
  const sd = SYMDEFS[c.sym];
  /* 同一位置的多个引脚（如 MOSFET 的 D/S）合并成一根线 + 一个标签 */
  const groups = new Map();
  for (const pd of sd.pins) {
    const key = `${pd.x},${pd.y},${pd.a}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(pd);
  }
  for (const [, grp] of groups) {
    const nets = new Set(grp.map(pd => pinNet.get(`${c.ref}.${pd.n}`)));
    if (nets.size !== 1) throw new Error(`${c.ref} 同位置引脚却属不同网络: ${[...nets].join(',')} (引脚 ${grp.map(g => g.n).join(',')})`);
    const net = [...nets][0];
    const pp = pinPos(c.ref, grp[0].n);
    /* 引脚方向：a=0 引脚朝右（连接点在左），a=180 朝左，a=90 朝上，a=270 朝下 */
    let dx = 0, dy = 0, labelAngle = 0;
    if (pp.a === 0) { dx = -STUB; labelAngle = 180; }
    else if (pp.a === 180) { dx = STUB; labelAngle = 0; }
    else if (pp.a === 90) { dy = STUB; labelAngle = 90; }
    else if (pp.a === 270) { dy = -STUB; labelAngle = 270; }

    const x1 = round(pp.x), y1 = round(pp.y);
    const x2 = round(pp.x + dx), y2 = round(pp.y + dy);
    w(`  (wire (pts (xy ${x1} ${y1}) (xy ${x2} ${y2})) (stroke (width 0) (type default)) (uuid "${uuid()}"))`);
    wireCount++;
    w(`  (global_label "${esc(net)}" (shape passive) (at ${x2} ${y2} ${labelAngle}) (fields_autoplaced yes)`);
    w(`    (effects (font (size 1.27 1.27)) (justify ${labelAngle === 180 ? 'right' : 'left'})) (uuid "${uuid()}"))`);
    labelCount++;
  }
}

/* ---- 收尾 ---- */
w(`  (sheet_instances (path "/" (page "1")))`);
w(`)`);

function round(v) { return Math.round(v * 1000) / 1000; }

/* ---- 一致性断言：标签名必须等于设计网络名 ---- */
const designNets = new Set(Object.keys(NETS));
for (const c of COMPONENTS)
  for (const pd of SYMDEFS[c.sym].pins) {
    const net = pinNet.get(`${c.ref}.${pd.n}`);
    if (!designNets.has(net)) collisions.push(`${c.ref}.${pd.n} -> ${net}`);
  }
if (collisions.length) { console.error('网络名不一致:', collisions); process.exit(1); }

export const kicadText = out.join('\n') + '\n';
export const stats = { components: COMPONENTS.length, wires: wireCount, labels: labelCount, nets: designNets.size };
