{"content": "/**
 * 构建：生成 .kicad_sch，然后【独立重新解析生成的文件】做端到端连接性校验，
 * 再导出网表与 BOM。
 */
import fs from 'node:fs';
import path from 'node:path';
import { kicadText, stats } from './kicad.mjs';
import { COMPONENTS, NETS, PIN_NAMES, PROJECT } from './design.mjs';

const OUT = path.resolve(import.meta.dirname, '..', 'hardware');
fs.mkdirSync(OUT, { recursive: true });

const schPath = path.join(OUT, 'motor-driver-V2.kicad_sch');
fs.writeFileSync(schPath, kicadText, 'utf8');

/* ============================================================
   独立重新解析
   ============================================================ */
const txt = kicadText;
const key = (x, y) => `${Math.round(x * 1000)},${Math.round(y * 1000)}`;

/* ---- 1) 解析 lib_symbols 里每个符号的引脚偏移 ---- */
const libPins = {};                       // symName -> [{n, px, py}]
{
  const libStart = txt.indexOf('(lib_symbols');
  const libEnd = txt.indexOf('\n  (sheet_instances');
  const libTxt = txt.slice(libStart, libEnd);
  const blocks = [...libTxt.matchAll(/\(symbol "mdrive:([A-Za-z0-9_]+)"([\s\S]*?)\n    \)\n/g)];
  for (const b of blocks) {
    const name = b[1];
    const body = b[2];
    const pins = [...body.matchAll(/\(pin \w+ line \(at (-?[\d.]+) (-?[\d.]+) (\d+)\) \(length ([\d.]+)\)\s*\(name "([^"]*)"[^)]*\)[^)]*\)\s*\(number "([^"]+)"/g)]
      .map(m => ({ n: m[6], px: +m[1], py: +m[2] }));
    libPins[name] = pins;
  }
}

/* ---- 2) 解析元件实例 ---- */
const instances = [];                     // {ref, sym, X, Y}
for (const m of txt.matchAll(/\(symbol \(lib_id "mdrive:([A-Za-z0-9_]+)"\) \(at (-?[\d.]+) (-?[\d.]+) (\d+)\)[\s\S]{0,400}?\(property "Reference" "([^"]+)"/g)) {
  instances.push({ sym: m[1], X: +m[2], Y: +m[3], ref: m[5] });
}

/* ---- 3) 引脚绝对坐标 → 反查表 ---- */
const pinAt = new Map();                  // coordKey -> ["R1.1", ...]
const pinOf = new Map();                  // "R1.1" -> coordKey
for (const inst of instances) {
  const pins = libPins[inst.sym];
  if (!pins) throw new Error(`解析不到符号 ${inst.sym} 的引脚`);
  for (const p of pins) {
    const x = inst.X + p.px, y = inst.Y - p.py;
    const k = key(x, y);
    if (!pinAt.has(k)) pinAt.set(k, []);
    pinAt.get(k).push(`${inst.ref}.${p.n}`);
    pinOf.set(`${inst.ref}.${p.n}`, k);
  }
}

/* ---- 4) 解析 wire 与 global_label ---- */
const wires = [...txt.matchAll(/\(wire \(pts \(xy (-?[\d.]+) (-?[\d.]+)\) \(xy (-?[\d.]+) (-?[\d.]+)\)\)/g)]
  .map(m => ({ a: key(+m[1], +m[2]), b: key(+m[3], +m[4]) }));
const labels = [...txt.matchAll(/\(global_label "([^"]+)" \(shape passive\) \(at (-?[\d.]+) (-?[\d.]+)/g)]
  .map(m => ({ net: m[1], at: key(+m[2], +m[3]) }));

/* ---- 5) 重建连接：wire 一端在 label，另一端在 pin ---- */
const labelAt = new Map();
for (const l of labels) labelAt.set(l.at, l.net);

const rebuilt = new Map();                // netName -> Set(pin)
const problems = [];
let dangling = 0, noLabel = 0, noPin = 0;
for (const wr of wires) {
  const netA = labelAt.get(wr.a), netB = labelAt.get(wr.b);
  const pinsA = pinAt.get(wr.a), pinsB = pinAt.get(wr.b);
  let net, pins;
  if (netA && pinsB) { net = netA; pins = pinsB; }
  else if (netB && pinsA) { net = netB; pins = pinsA; }
  else {
    if (!netA && !netB) noLabel++;
    else if (!pinsA && !pinsB) noPin++;
    else dangling++;
    continue;
  }
  if (!rebuilt.has(net)) rebuilt.set(net, new Set());
  for (const p of pins) rebuilt.get(net).add(p);
}

/* ---- 6) 与设计意图逐网络比对 ---- */
const report = [];
let mismatch = 0;
const allNets = new Set([...Object.keys(NETS), ...rebuilt.keys()]);
for (const net of [...allNets].sort()) {
  const want = new Set(NETS[net] ?? []);
  const got = rebuilt.get(net) ?? new Set();
  const missing = [...want].filter(p => !got.has(p));
  const extra = [...got].filter(p => !want.has(p));
  if (missing.length || extra.length) {
    mismatch++;
    report.push(`  ✗ ${net}: 缺失[${missing.join(',')}] 多出[${extra.join(',')}]`);
  }
}

/* ============================================================
   输出
   ============================================================ */
const lines = [];
lines.push('='.repeat(78));
lines.push(`${PROJECT.title}`);
lines.push(`Rev ${PROJECT.rev}   ${PROJECT.date}`);
lines.push('='.repeat(78));
lines.push('');
lines.push(`文件      : ${schPath}`);
lines.push(`元件数    : ${stats.components}`);
lines.push(`走线段数  : ${stats.wires}`);
lines.push(`网络标签数: ${stats.labels}`);
lines.push(`网络数    : ${stats.nets}`);
lines.push('');
lines.push('--- 生成的图元解析结果 ---');
lines.push(`  lib_symbols 解析出符号数 : ${Object.keys(libPins).length}`);
lines.push(`  元件实例解析数           : ${instances.length}`);
lines.push(`  wire 解析数              : ${wires.length}`);
lines.push(`  global_label 解析数      : ${labels.length}`);
lines.push(`  唯一引脚坐标点数         : ${pinAt.size}`);
lines.push('');
if (noLabel) lines.push(`  ⚠ 两端都没有标签的 wire : ${noLabel}`);
if (noPin) lines.push(`  ⚠ 两端都没有引脚的 wire : ${noPin}`);
if (dangling) lines.push(`  ⚠ 一端标签一端悬空的 wire: ${dangling}`);
lines.push('');
if (mismatch === 0) {
