lines.push('='.repeat(78));
lines.push(`${PROJECT.title}`);
lines.push(`Rev ${PROJECT.rev}   ${PROJECT.date}`);
lines.push('='.repeat(78));
lines.push('');
lines.push(`文件      : ${schPath}`);
lines.push(`元件数    : ${stats.components}`);
lines.push(`走线段数  : ${stats.wires}`);
lines.push(`网络标签数: ${stats.labels}`);
lines.push(`网络数    : ${stats.nets}`);
lines.push('');
lines.push('--- 生成的图元解析结果 ---');
lines.push(`  lib_symbols 解析出符号数 : ${Object.keys(libPins).length}`);
lines.push(`  元件实例解析数           : ${instances.length}`);
lines.push(`  wire 解析数              : ${wires.length}`);
lines.push(`  global_label 解析数      : ${labels.length}`);
lines.push(`  唯一引脚坐标点数         : ${pinAt.size}`);
lines.push('');
if (noLabel) lines.push(`  ⚠ 两端都没有标签的 wire : ${noLabel}`);
if (noPin) lines.push(`  ⚠ 两端都没有引脚的 wire : ${noPin}`);
if (dangling) lines.push(`  ⚠ 一端标签一端悬空的 wire: ${dangling}`);
