  lines.push('✓ 端到端校验通过：重新解析 .kicad_sch 得到的连接关系与设计意图逐网络完全一致。');
} else {
  lines.push(`✗ 端到端校验失败：${mismatch} 个网络不一致`);
  lines.push(...report);
}

console.log(lines.join('\n'));

/* ---- 网表（可读） ---- */
const netRows = [];
for (const [net, members] of Object.entries(NETS).sort()) {
  netRows.push(`${net}\t${members.length}\t${members.join(' ')}`);
}
fs.writeFileSync(path.join(OUT, 'netlist_V2.txt'),
  `# 网络\t成员数\t成员(位号.引脚)\n${netRows.join('\n')}\n`, 'utf8');

/* ---- 网表（KiCad .net 兼容的简易格式，便于其它工具导入） ---- */
const xnet = [];
xnet.push('(export (version "E")');
xnet.push('  (design');
xnet.push(`    (source "${path.basename(schPath)}")`);
xnet.push(`    (date "${PROJECT.date}")`);
xnet.push(`    (tool "mdrive-gen")`);
xnet.push('  )');
xnet.push('  (components');
for (const c of COMPONENTS) {
  xnet.push(`    (comp (ref "${c.ref}")`);
  xnet.push(`      (value "${c.val}")`);
  xnet.push(`      (footprint "${c.fp}")`);
  xnet.push(`      (description "${(c.desc ?? '').replace(/"/g, "'")}")`);
  xnet.push('    )');
}
xnet.push('  )');
xnet.push('  (nets');
let ni = 0;
for (const [net, members] of Object.entries(NETS).sort()) {
  ni++;
  xnet.push(`    (net (code "${ni}") (name "${net}")`);
  for (const m of members) {
    const dot = m.lastIndexOf('.');
    xnet.push(`      (node (ref "${m.slice(0, dot)}") (pin "${m.slice(dot + 1)}"))`);
  }
  xnet.push('    )');
}
xnet.push('  )');
xnet.push(')');
fs.writeFileSync(path.join(OUT, 'motor-driver-V2.net'), xnet.join('\n') + '\n', 'utf8');

/* ---- BOM ---- */
const bomLines = ['位号,数量,参数,封装,说明'];
const groups = new Map();
for (const c of COMPONENTS) {
  const k = `${c.val}|${c.fp}|${c.desc ?? ''}`;
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(c.ref);
}
const rows = [...groups.entries()].map(([k, refs]) => {
  const [val, fp, desc] = k.split('|');
  return { refs: refs.sort(), val, fp, desc };
}).sort((a, b) => a.refs[0].localeCompare(b.refs[0], 'en', { numeric: true }));
for (const r of rows) bomLines.push(`${r.refs.join(' ')},${r.refs.length},"${r.val}","${r.fp}","${r.desc}"`);
fs.writeFileSync(path.join(OUT, 'BOM_V2.csv'), '\uFEFF' + bomLines.join('\n') + '\n', 'utf8');

