{"content": "/**
 * 从生成好的 .kicad_sch 渲染工程图 SVG。
 * 独立解析该文件（不复用生成器的中间状态），因此渲染结果本身就是一次交叉验证。
 */
import fs from 'node:fs';
import path from 'node:path';
import { NET_CLASS } from './design.mjs';

const SRC = path.resolve(import.meta.dirname, '..', 'hardware', 'motor-driver-V2.kicad_sch');
const DST = path.resolve(import.meta.dirname, '..', 'hardware', 'motor-driver-V2.svg');
const txt = fs.readFileSync(SRC, 'utf8');

/* ---------- 解析 lib_symbols ---------- */
const lib = {};
{
  const a = txt.indexOf('(lib_symbols');
  const b = txt.indexOf('\n  (sheet_instances');
  const seg = txt.slice(a, b);
  const starts = [...seg.matchAll(/\(symbol "mdrive:([A-Za-z0-9_]+)"/g)];
  for (let i = 0; i < starts.length; i++) {
    const name = starts[i][1];
    const body = seg.slice(starts[i].index, i + 1 < starts.length ? starts[i + 1].index : seg.length);
    const gfx = [];
    for (const m of body.matchAll(/\(rectangle \(start (-?[\d.]+) (-?[\d.]+)\) \(end (-?[\d.]+) (-?[\d.]+)\)/g))
      gfx.push({ t: 'rect', x1: +m[1], y1: +m[2], x2: +m[3], y2: +m[4] });
    for (const m of body.matchAll(/\(polyline \(pts ((?:\(xy -?[\d.]+ -?[\d.]+\)\s*)+)\)/g)) {
      const pts = [...m[1].matchAll(/\(xy (-?[\d.]+) (-?[\d.]+)\)/g)].map(p => [+p[1], +p[2]]);
      gfx.push({ t: 'poly', pts });
    }
    const pins = [];
    for (const pb of body.split('(pin ').slice(1)) {
      const at = pb.match(/^\w+ line \(at (-?[\d.]+) (-?[\d.]+) (\d+)\) \(length ([\d.]+)\)/);
      const nm = pb.match(/\(name "([^"]*)"/);
      const num = pb.match(/\(number "([^"]+)"/);
      if (at && num) pins.push({ x: +at[1], y: +at[2], a: +at[3], l: +at[4], name: nm ? nm[1] : '~', num: num[1] });
    }
    lib[name] = { gfx, pins };
  }
}

/* ---------- 解析实例 ---------- */
const insts = [];
for (const m of txt.matchAll(/\(symbol \(lib_id "mdrive:([A-Za-z0-9_]+)"\) \(at (-?[\d.]+) (-?[\d.]+) (\d+)\)[\s\S]{0,600}?\(property "Reference" "([^"]+)" (?:\(at (-?[\d.]+) (-?[\d.]+)[^)]*\))[\s\S]{0,200}?\(property "Value" "([^"]*)"/g))
  insts.push({ sym: m[1], X: +m[2], Y: +m[3], ref: m[5], val: m[7] });

/* ---------- 解析 wire / label ---------- */
const wires = [...txt.matchAll(/\(wire \(pts \(xy (-?[\d.]+) (-?[\d.]+)\) \(xy (-?[\d.]+) (-?[\d.]+)\)\)/g)]
  .map(m => ({ x1: +m[1], y1: +m[2], x2: +m[3], y2: +m[4] }));
const labels = [...txt.matchAll(/\(global_label "([^"]+)" \(shape passive\) \(at (-?[\d.]+) (-?[\d.]+) (\d+)\)/g)]
  .map(m => ({ net: m[1], x: +m[2], y: +m[3], a: +m[4] }));

/* ---------- 绘制 ---------- */
const S = 6;                       // px per mm
const W = 594, H = 420;            // A2
const e = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const X = (x) => +(x * S).toFixed(2);
const Y = (y) => +(y * S).toFixed(2);

const CLASS_COLOR = {
  power: '#c0392b', phase: '#d35400', gnd: '#2c3e50', boot: '#8e44ad',
  gate: '#1f6f3f', analog: '#1f4e9c', logic: '#7d3c98', other: '#555',
};
const o = [];
o.push(`<svg xmlns="http://www.w3.org/2000/svg" width="${W * S}" height="${H * S}" viewBox="0 0 ${W * S} ${H * S}" font-family="Consolas,Menlo,monospace">`);
o.push(`<rect width="${W * S}" height="${H * S}" fill="#fffdf7"/>`);

/* 图框 */
o.push(`<rect x="${X(5)}" y="${Y(5)}" width="${X(W - 10)}" height="${Y(H - 10)}" fill="none" stroke="#333" stroke-width="1.6"/>`);
o.push(`<rect x="${X(8)}" y="${Y(8)}" width="${X(W - 16)}" height="${Y(H - 16)}" fill="none" stroke="#333" stroke-width="0.6"/>`);

/* 元件图形 */
for (const it of insts) {
  const L = lib[it.sym];
  if (!L) continue;
  const P = (px, py) => [X(it.X + px), Y(it.Y - py)];
  for (const g of L.gfx) {
    if (g.t === 'rect') {
      const [x1, y1] = P(Math.min(g.x1, g.x2), Math.max(g.y1, g.y2));
      const [x2, y2] = P(Math.max(g.x1, g.x2), Math.min(g.y1, g.y2));
      o.push(`<rect x="${x1}" y="${y1}" width="${(x2 - x1).toFixed(2)}" height="${(y2 - y1).toFixed(2)}" fill="#f4f8ff" stroke="#0b3d91" stroke-width="1.1"/>`);
    } else {
      const d = g.pts.map((p, i) => `${i ? 'L' : 'M'}${P(p[0], p[1]).join(' ')}`).join(' ');
      o.push(`<path d="${d}" fill="none" stroke="#0b3d91" stroke-width="1.3"/>`);
    }
  }
  /* 引脚 */
  for (const p of L.pins) {
    const dx = p.a === 0 ? p.l : p.a === 180 ? -p.l : 0;
    const dy = p.a === 90 ? p.l : p.a === 270 ? -p.l : 0;
    const [ax, ay] = P(p.x, p.y);
    const [bx, by] = P(p.x + dx, p.y + dy);
    o.push(`<line x1="${ax}" y1="${ay}" x2="${bx}" y2="${by}" stroke="#0b3d91" stroke-width="1"/>`);
    o.push(`<circle cx="${ax}" cy="${ay}" r="1.6" fill="#0b3d91"/>`);
    if (p.name && p.name !== '~') {
      const tx = p.a === 0 ? bx + 3 : p.a === 180 ? bx - 3 : bx + 3;
      o.push(`<text x="${tx}" y="${(ay + 3).toFixed(1)}" font-size="7" fill="#0b3d91" text-anchor="${p.a === 180 ? 'end' : 'start'}">${e(p.name)}</text>`);
    }
    o.push(`<text x="${ax}" y="${(ay - 3).toFixed(1)}" font-size="6" fill="#888" text-anchor="middle">${e(p.num)}</text>`);
  }
  /* 位号 / 参数 */
  o.push(`<text x="${X(it.X - 6)}" y="${Y(it.Y - (it.sym === 'NMOS' ? -9.5 : it.sym === 'FD6288T' || it.sym === 'XL7005A' || it.sym === 'CONN2X8' ? -18 : 4.5))}" font-size="11" font-weight="bold" fill="#111">${e(it.ref)}</text>`);
  o.push(`<text x="${X(it.X - 6)}" y="${Y(it.Y - (it.sym === 'NMOS' ? -12 : it.sym === 'FD6288T' || it.sym === 'XL7005A' || it.sym === 'CONN2X8' ? -20.5 : 7))}" font-size="9" fill="#444">${e(it.val)}</text>`);
}

/* 走线 */
for (const w of wires)
  o.push(`<line x1="${X(w.x1)}" y1="${Y(w.y1)}" x2="${X(w.x2)}" y2="${Y(w.y2)}" stroke="#1f6f3f" stroke-width="1.3"/>`);

/* 网络标签 */
for (const l of labels) {
  const c = CLASS_COLOR[NET_CLASS[l.net] ?? 'other'];
  const right = l.a === 180;
  const tx = X(l.x) + (right ? -4 : 4);
  const anchor = right ? 'end' : 'start';
  o.push(`<circle cx="${X(l.x)}" cy="${Y(l.y)}" r="2" fill="${c}"/>`);
  o.push(`<text x="${tx}" y="${(Y(l.y) + 3.2).toFixed(1)}" font-size="8.5" fill="${c}" text-anchor="${anchor}">${e(l.net)}</text>`);
}

/* 标题栏 */
const tb = [
  ['三相无刷电机驱动板 V2.0', 13, '#111'],
  ['无感六步换向 + 反电动势过零检测', 9, '#333'],
  ['过零检测：控制板 HC32F072 的 3×VC 比较器 + 虚拟中性点', 8, '#333'],
  ['母线 24–36V ｜ 96 位号 ｜ PGND/AGND 经 R47(0Ω) 单点星接', 8, '#333'],
  ['Rev V2.0   2026-09-11   KiCad 格式（可导入嘉立创EDA专业版）', 8, '#333'],
];
tb.forEach(([t, sz, col], i) => {
  o.push(`<text x="${X(W - 12)}" y="${Y(H - 14 - (tb.length - 1 - i) * 6)}" font-size="${sz}" fill="${col}" text-anchor="end">${e(t)}</text>`);
});

/* 图例 */
const legend = [['电源/母线', 'power'], ['相线', 'phase'], ['地', 'gnd'], ['自举', 'boot'], ['栅极', 'gate'], ['模拟/采样', 'analog'], ['逻辑/PWM', 'logic']];
o.push(`<text x="${X(W - 12)}" y="${Y(50)}" font-size="10" font-weight="bold" fill="#111" text-anchor="end">网络颜色图例</text>`);
legend.forEach(([t, k], i) => {
  o.push(`<rect x="${X(W - 12) - 8}" y="${Y(53 + i * 5)}" width="8" height="3" fill="${CLASS_COLOR[k]}"/>`);
  o.push(`<text x="${X(W - 12) - 12}" y="${Y(55.2 + i * 5)}" font-size="8.5" fill="#333" text-anchor="end">${e(t)}</text>`);
});

/* 功能块标注 */
const blocks = [
  ['① 功率级（三相半桥）', 20, 22],
  ['② 栅极电阻 + 栅源下拉', 20, 28],
  ['③ 栅驱动 FD6288T + 自举', 190, 22],
  ['④ 辅助电源 XL7005A + EN 选择', 285, 22],
  ['⑤ 母线电容 + 保护', 20, 150],
  ['⑥ PWM 输入（外接核心板）', 20, 200],
  ['⑦ 相电压采集 + 虚拟中性点 ★本次核心', 20, 275],
  ['⑧ 母线/过流采样', 235, 200],
  ['⑨ 连接器', 290, 275],
];
for (const [t, x, y] of blocks) {
  o.push(`<rect x="${X(x - 3)}" y="${Y(y - 4.5)}" width="${(t.length * 4.6 + 8).toFixed(0)}" height="9" fill="#fff" stroke="none"/>`);
  o.push(`<text x="${X(x)}" y="${Y(y)}" font-size="12" font-weight="bold" fill="#a33">${e(t)}</text>`);
}

o.push('</svg>');
fs.writeFileSync(DST, o.join('\n'), 'utf8');
console.log(`SVG 已生成: ${DST}`);
console.log(`  元件实例 ${insts.length} / 走线 ${wires.length} / 标签 ${labels.length}`);
console.log(`  图幅 A2 (${W}×${H} mm)，比例 ${S} px/mm`);
", "file_path": "C:\Users\limer\Desktop\motor-drive\Soft\_gen\render.mjs"}

