block.arguments:
{"command": "$root = "C:\Users\limer\Desktop\motor-drive\Soft"
Set-Location $root
$dirs = @(
  "01_工程\_生成器",
  "02_参考\芯片知识库",
  "02_参考\记忆对话\解压内容",
  "03_审核\原始图纸解析"
)
foreach ($d in $dirs) { New-Item -ItemType Directory -Force -Path (Join-Path $root $d) | Out-Null }

# ---- 01_工程：交付物 ----
$eng = @("motor-driver-V2.kicad_sch","motor-driver-V2.net","netlist_V2.txt","BOM_V2.csv","motor-driver-V2.svg","V2.0_设计规格与计算书.md")
foreach ($f in $eng) { if (Test-Path "hardware\$f") { Move-Item -LiteralPath "hardware\$f" -Destination "01_工程\" -Force } }
if (Test-Path "hardware\preview_full.png") { Move-Item -LiteralPath "hardware\preview_full.png" -Destination "01_工程\motor-driver-V2.png" -Force }
Get-ChildItem "_gen" -File | ForEach-Object { Move-Item -LiteralPath $_.FullName -Destination "01_工程\_生成器\" -Force }
if (Test-Path "hardware") { Remove-Item "hardware" -Recurse -Force }
if (Test-Path "_gen") { Remove-Item "_gen" -Recurse -Force }

# ---- 02_参考：输入与知识 ----
foreach ($f in @("SCH_Schematic1_2026-09-09.pdf","motor-driver.eprj2")) { if (Test-Path $f) { Move-Item -LiteralPath $f -Destination "02_参考\" -Force } }
foreach ($f in @("HC32F072JATA.md","FD6288T.md")) { if (Test-Path $f) { Move-Item -LiteralPath $f -Destination "02_参考\芯片知识库\" -Force } }
Get-ChildItem -Filter "dsh-session-*.zip" | ForEach-Object { Move-Item -LiteralPath $_.FullName -Destination "02_参考\记忆对话\" -Force }
if (Test-Path "_mem\session.jsonl") { Move-Item -LiteralPath "_mem\session.jsonl" -Destination "02_参考\记忆对话\解压内容\" -Force }
if (Test-Path "_mem\subagents") { Move-Item -LiteralPath "_mem\subagents" -Destination "02_参考\记忆对话\解压内容\" -Force }
if (Test-Path "_mem\media") { Move-Item -LiteralPath "_mem\media" -Destination "02_参考\记忆对话\解压内容\" -Force }
if (Test-Path "_mem") { Remove-Item "_mem" -Recurse -Force }

# ---- 03_审核：分析与校验 ----
foreach ($f in @("analysis_notes.md")) { if (Test-Path $f) { Move-Item -LiteralPath $f -Destination "03_审核\" -Force } }
foreach ($f in @("分析报告.md","修复方案.md","V1.1_权威网表与现状.md","F3_低边源极修改方案.md")) {
  if (Test-Path "_analysis\$f") { Move-Item -LiteralPath "_analysis\$f" -Destination "03_审核\" -Force }
}
if (Test-Path "_analysis") { Move-Item -LiteralPath "_analysis" -Destination "03_审核\原始图纸解析" -Force }
Write-Output "=== 整理后 ==="; Get-ChildItem -Recurse -Force | Where-Object { -not $_.PSIsContainer } | ForEach-Object { $_.FullName.Replace($root,'.') } | Sort-Object", "description": "Reorganize workspace into three categorized folders"}

