  w(`    (property "Datasheet" "" (at ${p.x} ${p.y} 0) (effects (font (size 1.27 1.27)) hide))`);
  const seen = new Set();
  for (const pd of sd.pins) { if (seen.has(pd.n)) continue; seen.add(pd.n); w(`    (pin "${pd.n}" (uuid "${uuid()}"))`); }
