    const net = [...nets][0];
    const pp = pinPos(c.ref, grp[0].n);

    let dx, labelAngle;
    if (pp.a === 0) { dx = -STUB; labelAngle = 180; }
    else if (pp.a === 180) { dx = STUB; labelAngle = 0; }
