for (const c of COMPONENTS)
  for (const pd of SYMDEFS[c.sym].pins)
    if (!designNets.has(pinNet.get(`${c.ref}.${pd.n}`)))
      throw new Error(`网络名不在设计中: ${c.ref}.${pd.n}`);

