      o.push(`<rect x="${x1}" y="${y1}" width="${(x2 - x1).toFixed(2)}" height="${(y2 - y1).toFixed(2)}" fill="#f2f7ff" stroke="#0b3d91" stroke-width="1.1"/>`);
